  description = "When true (and email_redaction_enabled is false), tag logs that would have been redacted with vector_email_detected=true instead of replacing. Useful for non-prod visibility without masking."
  type        = bool
  default     = false
}

variable "email_redaction_replacement" {
  description = "String that replaces matched email addresses"
